modules["引擎/events.js"]=function(require,module,exports){
// 突发事件（爆种/爆冷）+ 心态：通过钩子接入交战判定
// 高光：关键交火中超常发挥；失误：关键时机掉链子。概率由熟练度档位与心态共同调制
const cfg = require('./config');

const P = cfg.proficiency;
const M = cfg.mentality;

// 是否关键时机：进点抢先/反抢先、残局 1vN
function isKeyMoment(ctx) {
  if (ctx.entry) return true;
  return ctx.round.aliveCount(ctx.att.side) === 1; // 残局
}

function combatHook(ctx, p) {
  const u = ctx.att;
  const round = ctx.round;
  // 心态对战力的小幅修正
  p *= 1 + (u.mentality || 0) * M.combatSwing;
  if(round.suppressedEventSides?.has(u.side))return p;
  if (!isKeyMoment(ctx)) return p;
  // 爆种 / 爆冷
  const popP = (u.inPool ? P.popOffIn : P.popOffOut) * (1 + (u.mentality || 0) * M.eventSwing);
  const whiffP = (u.inPool ? P.whiffIn : P.whiffOut) * (1 - (u.mentality || 0) * M.eventSwing);
  const r = round.rng();
  if (r < popP) {
    round.emit('pop_off', { node: u.node, unit: u.name, agent: u.agent });
    round.stats.popOffs++;
    return p * P.popOffMult;
  }
  if (r < popP + whiffP) {
    round.emit('whiff', { node: u.node, unit: u.name, agent: u.agent });
    round.stats.whiffs++;
    return p * P.whiffMult;
  }
  return p;
}

// 回合结束后的心态更新（在 match 层调用）
function updateMentality(units, won, scoreUs, scoreThem, streak) {
  for (const u of units) {
    let m = u.mentality || 0;
    if (won) m += M.winGain + M.streakBonus * Math.max(streak - 1, 0);
    else m -= M.lossDrop + M.streakBonus * Math.max(streak - 1, 0);
    const gap = scoreUs - scoreThem;
    if (gap <= -3) m -= M.gapPressure * Math.floor(-gap / 3); // 落后承压
    if (gap >= 3) m += M.gapPressure * Math.floor(gap / 3) * 0.5; // 领先略松
    m += M.killBoost * (u.roundKills || 0);
    if (!u.alive && !(u.roundKills > 0)) m -= M.deathDrop;
    u.mentality = Math.max(-1, Math.min(1, m));
  }
}

function attachHooks(hooks) {
  hooks.beforeKillRoll.push(combatHook);
}

module.exports = { attachHooks, updateMentality };

};
modules["引擎/squad.js"]=function(require,module,exports){
// 玩家可将固定战术槽位交给指定选手；只重排职责，不生成技能或额外属性。
function swapRole(intent, a, b) {
  if (a === b) return;
  [intent.roles[a], intent.roles[b]] = [intent.roles[b], intent.roles[a]];
  [intent.homes[a], intent.homes[b]] = [intent.homes[b], intent.homes[a]];
  if (intent.carrier === a) intent.carrier = b;
  else if (intent.carrier === b) intent.carrier = a;
}

function applyRolePreferences(intent, preferences) {
  if (!preferences) return intent;
  if (intent.side === 'atk') {
    if (intent.family === 'lurk' && Number.isInteger(preferences.lurker)) swapRole(intent, 4, preferences.lurker);
    if (intent.family === 'fake' && Number.isInteger(preferences.decoy)) swapRole(intent, 0, preferences.decoy);
    if (Number.isInteger(preferences.carrier)) intent.carrier = preferences.carrier;
  } else if (intent.family === 'stack' && Number.isInteger(preferences.anchor)) {
    swapRole(intent, 4, preferences.anchor);
  }
  return intent;
}

module.exports = { applyRolePreferences };

};
modules["引擎/match-rules.js"]=function(require,module,exports){
// All consumers use these rules for score termination and side selection.
function matchOver(scoreA, scoreB, rules) {
  return Math.max(scoreA, scoreB) >= rules.firstTo && Math.abs(scoreA - scoreB) >= 2;
}
function attackSide(roundIndex, rules) {
  const initial = rules.initialAttacker || 'A';
  if (!['A', 'B'].includes(initial)) throw new Error('初始攻方必须为 A 或 B');
  const opposite = initial === 'A' ? 'B' : 'A';
  if (roundIndex < rules.halfRounds) return initial;
  if (roundIndex < rules.halfRounds * 2) return opposite;
  return (roundIndex - rules.halfRounds * 2) % 2 === 0 ? initial : opposite;
}
function validateMatchRules(rules) {
  if (!Number.isInteger(rules.halfRounds) || rules.halfRounds < 1 || rules.firstTo !== rules.halfRounds + 1
    || !Number.isFinite(rules.overtimeMoney) || rules.overtimeMoney < 0) throw new Error('无效赛制：胜分应为半场回合数加一');
  attackSide(0, rules);
}
module.exports = { matchOver, attackSide, validateMatchRules };

};
modules["引擎/coach-observation.js"]=function(require,module,exports){
// Coach estimates use sightings and publicly visible plants, never enemy plans.
function estimate(events, observerSide, map) {
  const sightings = events.filter(e => e.type === 'sighting' && e.side === observerSide);
  const targets = new Set(sightings.map(e => e.targetId || e.target));
  if (targets.size < 2) return null;
  const regions = sightings.map(e => map.region(e.node));
  if (observerSide === 'def') {
    const early = new Set(sightings.filter(e => e.t <= 12).map(e => e.targetId || e.target)).size;
    if (early >= 3) return 'rush';
    if (regions.filter(r => r === 'mid').length >= sightings.length / 2) return 'mid';
    const plant = events.find(e => e.type === 'plant');
    const first = sightings[0];
    if (plant && map.region(first.node) !== plant.site && first.t < plant.t - 8) return 'fake';
    if (regions.includes('A') && regions.includes('B')) return 'lurk';
    return 'contact';
  }
  if (sightings.some(e => ['t_spawn', 'a_main', 'b_main'].includes(e.node))) return 'flank';
  if (regions.filter(r => r === 'mid').length >= sightings.length / 2) return 'push';
  const plant = events.find(e => e.type === 'plant');
  if (plant && sightings.filter(e => e.t > plant.t).length >= sightings.length / 2) return 'retake';
  if (new Set(regions).size === 1 && targets.size >= 3) return 'trap';
  return 'hold';
}
module.exports = { estimate };

};
